 * Serialises to {@code {"errors": ["field", ...]}}.
 */
public class RequiredFieldsErrorResponse {

    private final List<String> errors;

    public RequiredFieldsErrorResponse(List<String> errors) {
        this.errors = errors;
    }

    public List<String> getErrors() {
        return errors;
    }
}

